create extension if not exists pg_net;
alter table public.customers add column birth_date date check (birth_date is null or birth_date between date '1900-01-01' and current_date);
alter table public.customers add column phone_verified_at timestamptz;
alter table public.customers add column whatsapp_updates boolean not null default false;
alter table public.customers add column whatsapp_marketing boolean not null default false;
alter table public.customers add column portal_deleted_at timestamptz;
alter table public.campaigns add column birthday_voucher boolean not null default false;
alter table public.campaigns add column sent_at timestamptz;
create table app_private.wa_connections(tenant_id uuid primary key references public.tenants(id),secret_id uuid not null,enabled boolean not null default false,worker_secret text not null default encode(extensions.gen_random_bytes(32),'hex'));
create table app_private.wa_otps(id uuid primary key,tenant_id uuid not null,phone text not null,code_hash text not null,ip_hash text not null,attempts int not null default 0,expires_at timestamptz not null default now()+interval '5 minutes',created_at timestamptz not null default now(),used_at timestamptz);
create index wa_otp_rate on app_private.wa_otps(tenant_id,phone,created_at desc);
create index wa_otp_ip on app_private.wa_otps(ip_hash,created_at desc);
create table app_private.wa_sessions(token_hash text primary key,tenant_id uuid not null,customer_id uuid not null references public.customers(id),created_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '30 days');
create table app_private.wa_outbox(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,customer_id uuid,kind text not null check(kind in('otp','order','birthday')),dedupe text not null,phone text not null,payload jsonb not null,state text not null default 'pending' check(state in('pending','processing','sent','delivered','read','failed','uncertain','cancelled')),attempts int not null default 0,available_at timestamptz not null default now(),created_at timestamptz not null default now(),sent_at timestamptz,provider_id text unique,last_error text,unique(tenant_id,dedupe));
create index wa_pending on app_private.wa_outbox(tenant_id,available_at) where state='pending';
create table app_private.wa_birthdays(tenant_id uuid not null,phone_hash text not null,year int not null,customer_id uuid not null,campaign_id uuid not null references public.campaigns(id),primary key(tenant_id,phone_hash,year));
alter table app_private.wa_connections enable row level security;
alter table app_private.wa_otps enable row level security;
alter table app_private.wa_sessions enable row level security;
alter table app_private.wa_outbox enable row level security;
alter table app_private.wa_birthdays enable row level security;
create function app_private.wa_phone(p text) returns text language sql immutable set search_path='' as $$select case when length(regexp_replace(coalesce(p,''),'\D','','g')) in(10,11) then '55'||regexp_replace(p,'\D','','g') else regexp_replace(coalesce(p,''),'\D','','g') end$$;
create function app_private.wa_phase(s text,m uuid) returns text language sql immutable set search_path='' as $$select case when lower(s)='aceito' then 'aceito' when lower(s) in('em preparo','em_preparo') then 'em preparo' when lower(s) in('enviado','despachado') or (lower(s)='pronto' and m is not null) then 'enviado' when lower(s)='pronto' then 'pronto' else lower(s) end$$;
create function app_private.wa_customer(t uuid,token text) returns uuid language sql stable security definer set search_path='' as $$select s.customer_id from app_private.wa_sessions s join public.customers c on c.id=s.customer_id and c.tenant_id=s.tenant_id where s.tenant_id=t and s.token_hash=encode(extensions.digest(token,'sha256'),'hex') and s.expires_at>now() and c.portal_deleted_at is null$$;
create function app_private.wa_account(t uuid,cid uuid) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('customer',jsonb_build_object('id',c.id,'name',c.name,'phone',c.phone,'address',c.address,'birthDate',c.birth_date,'updates',c.whatsapp_updates,'marketing',c.whatsapp_marketing),'orders',coalesce((select jsonb_agg(x) from(select o.id,o.ticket_number as "ticketNumber",o.items,o.total,app_private.wa_phase(o.status,o.motoboy_id) as status,o.created_at as created,o.updated_at as updated from public.orders o where o.tenant_id=t and (o.customer_id=cid or app_private.wa_phone(o.customer_phone)=app_private.wa_phone(c.phone)) order by o.created_at desc limit 100)x),'[]'::jsonb),'campaigns',coalesce((select jsonb_agg(x) from(select v.id,v.title,v.description,v.type,v.discount_percent as "discountPercent",v.discount_amount as "discountAmount",v.target_product_id as "targetProductId",v.voucher_code as "voucherCode",v.expires_at as "expiresAt" from public.campaigns v where v.tenant_id=t and v.customer_id=cid and v.active and not v.used and (v.expires_at is null or v.expires_at>now()) order by v.created_at desc limit 100)x),'[]'::jsonb)) from public.customers c where c.tenant_id=t and c.id=cid and c.portal_deleted_at is null$$;
create function app_private.wa_order_event() returns trigger language plpgsql security definer set search_path='' as $$declare phase text; c public.customers;begin
 phase:=app_private.wa_phase(new.status,new.motoboy_id);
 if phase not in('aceito','em preparo','pronto','enviado') or (tg_op='UPDATE' and phase=app_private.wa_phase(old.status,old.motoboy_id)) then return new;end if;
 select * into c from public.customers where tenant_id=new.tenant_id and portal_deleted_at is null and phone_verified_at is not null and whatsapp_updates and app_private.wa_phone(phone)=app_private.wa_phone(new.customer_phone) limit 1;
 if c.id is not null then insert into app_private.wa_outbox(tenant_id,customer_id,kind,dedupe,phone,payload) values(new.tenant_id,c.id,'order','order:'||new.id||':'||phase,app_private.wa_phone(c.phone),jsonb_build_object('name',c.name,'ticket',new.ticket_number,'phase',phase)) on conflict(tenant_id,dedupe) do nothing;end if;return new;end$$;
create trigger wa_order_notifications after insert or update of status,motoboy_id on public.orders for each row execute function app_private.wa_order_event();
create function app_private.wa_queue_birthdays(p_at timestamptz default now()) returns integer language plpgsql security definer set search_path='' as $$declare c public.customers;v uuid;h text;day date:=(p_at at time zone 'America/Sao_Paulo')::date;n int:=0;begin
 for c in select c.* from public.customers c join app_private.wa_connections w on w.tenant_id=c.tenant_id and w.enabled where c.portal_deleted_at is null and c.phone_verified_at is not null and c.whatsapp_marketing and c.birth_date is not null and extract(hour from p_at at time zone 'America/Sao_Paulo')>=9 and (to_char(c.birth_date,'MM-DD')=to_char(day,'MM-DD') or (to_char(c.birth_date,'MM-DD')='02-29' and to_char(day,'MM-DD')='02-28' and extract(day from day+1)=1)) loop
 h:=encode(extensions.digest(c.tenant_id||':'||app_private.wa_phone(c.phone),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended(c.tenant_id||h||extract(year from day)::text,0));
 if exists(select 1 from app_private.wa_birthdays where tenant_id=c.tenant_id and phone_hash=h and year=extract(year from day)::int) then continue;end if;
 v:=gen_random_uuid();insert into public.campaigns(id,tenant_id,customer_id,customer_phone,customer_name,type,title,description,discount_percent,discount_amount,active,used,voucher_code,birthday_voucher) values(v,c.tenant_id,c.id,c.phone,c.name,'voucher_10','Feliz aniversário! 10% de desconto','Um convite para celebrar com a gente. Válido por 72 horas após o envio.',10,0,false,false,'LOY-'||upper(encode(extensions.gen_random_bytes(5),'hex')),true);
 insert into app_private.wa_birthdays values(c.tenant_id,h,extract(year from day)::int,c.id,v);
 insert into app_private.wa_outbox(tenant_id,customer_id,kind,dedupe,phone,payload) select c.tenant_id,c.id,'birthday','birthday:'||v,app_private.wa_phone(c.phone),jsonb_build_object('name',c.name,'campaignId',v,'code',voucher_code) from public.campaigns where id=v;n:=n+1;end loop;return n;end$$;
-- Service-role-only RPC. No browser may select private OTPs, tokens, credentials or queues.
create function public.customer_whatsapp_api(p_tenant uuid,p_action text,p_data jsonb default '{}',p_token text default '',p_operator uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$declare c uuid;o app_private.wa_otps;cfg jsonb;sid uuid;oid uuid;token text;result jsonb;e app_private.wa_outbox;ph text;bdate date;begin
 if p_action in('status','worker_config','admin_status','configure','webhook_config') then
 select decrypted_secret::jsonb into cfg from vault.decrypted_secrets where id=(select secret_id from app_private.wa_connections where tenant_id=p_tenant);
 if p_action='status' then return jsonb_build_object('ready',coalesce((select enabled from app_private.wa_connections where tenant_id=p_tenant),false));end if;
 if p_action='worker_config' then if not exists(select 1 from app_private.wa_connections where tenant_id=p_tenant and enabled and worker_secret=p_token) then raise exception 'Worker não autorizado';end if;return cfg;end if;
 if p_action='webhook_config' then return coalesce(cfg,'{}');end if;
 if not exists(select 1 from public.tenant_memberships where tenant_id=p_tenant and user_id=p_operator and active and role='owner') then raise exception 'Apenas o proprietário pode configurar o WhatsApp';end if;
 if p_action='configure' then
 cfg:=coalesce(cfg,'{}')||(p_data-'enabled');select secret_id into sid from app_private.wa_connections where tenant_id=p_tenant;
 if sid is null then sid:=vault.create_secret(cfg::text);insert into app_private.wa_connections(tenant_id,secret_id,enabled) values(p_tenant,sid,coalesce((p_data->>'enabled')::boolean,false));else perform vault.update_secret(sid,cfg::text);update app_private.wa_connections set enabled=coalesce((p_data->>'enabled')::boolean,false) where tenant_id=p_tenant;end if;end if;
 return jsonb_build_object('ready',coalesce((select enabled from app_private.wa_connections where tenant_id=p_tenant),false),'configured',cfg is not null,'phoneNumberId',cfg->>'phoneNumberId','wabaId',cfg->>'wabaId','apiVersion',cfg->>'apiVersion','otpTemplate',cfg->>'otpTemplate','orderTemplate',cfg->>'orderTemplate','birthdayTemplate',cfg->>'birthdayTemplate','verifyToken',cfg->>'verifyToken','recent',coalesce((select jsonb_agg(x) from(select kind,state,created_at,sent_at,last_error from app_private.wa_outbox where tenant_id=p_tenant order by created_at desc limit 30)x),'[]'::jsonb));end if;
 if p_action='request_otp' then
 if not exists(select 1 from app_private.wa_connections where tenant_id=p_tenant and enabled) then raise exception 'Conecte o WhatsApp da loja para enviar o código de verificação.';end if;
 ph:=app_private.wa_phone(p_data->>'phone');if ph!~'^55[1-9][0-9]{9,10}$' then raise exception 'Informe um telefone brasileiro com DDD';end if;perform pg_advisory_xact_lock(hashtextextended(p_tenant||ph,0));
 if (select count(*) from app_private.wa_otps where tenant_id=p_tenant and phone=ph and created_at>now()-interval '1 hour')>=3 or (select count(*) from app_private.wa_otps where ip_hash=p_data->>'ipHash' and created_at>now()-interval '1 hour')>=10 then raise exception 'Limite de códigos atingido. Tente novamente em uma hora.';end if;
 if exists(select 1 from app_private.wa_otps where tenant_id=p_tenant and phone=ph and created_at>now()-interval '60 seconds') then raise exception 'Aguarde 60 segundos para reenviar.';end if;
 oid:=gen_random_uuid();update app_private.wa_otps set used_at=now() where tenant_id=p_tenant and phone=ph and used_at is null;
 insert into app_private.wa_otps(id,tenant_id,phone,code_hash,ip_hash) values(oid,p_tenant,ph,encode(extensions.digest(oid||':'||(p_data->>'code'),'sha256'),'hex'),p_data->>'ipHash');
 insert into app_private.wa_outbox(tenant_id,kind,dedupe,phone,payload) values(p_tenant,'otp','otp:'||oid,ph,jsonb_build_object('code',p_data->>'code'));return jsonb_build_object('challengeId',oid,'expiresIn',300);end if;
 if p_action='verify_otp' then
 select * into o from app_private.wa_otps where id=(p_data->>'challengeId')::uuid and tenant_id=p_tenant for update;
 if o.id is null or o.used_at is not null or o.expires_at<=now() or o.attempts>=5 then return jsonb_build_object('error','Código expirado ou indisponível. Solicite outro.');end if;
 update app_private.wa_otps set attempts=attempts+1 where id=o.id;
 if o.code_hash<>encode(extensions.digest(o.id||':'||(p_data->>'code'),'sha256'),'hex') then return jsonb_build_object('error','Código incorreto.');end if;update app_private.wa_otps set used_at=now() where id=o.id;
 select id into c from public.customers where tenant_id=p_tenant and app_private.wa_phone(phone)=o.phone and portal_deleted_at is null order by created_at limit 1 for update;
 if c is null then insert into public.customers(tenant_id,name,phone,phone_verified_at) values(p_tenant,left(trim(p_data->>'name'),100),o.phone,now()) returning id into c;else update public.customers set phone_verified_at=now() where id=c;end if;
 token:=encode(extensions.gen_random_bytes(32),'hex');insert into app_private.wa_sessions(token_hash,tenant_id,customer_id) values(encode(extensions.digest(token,'sha256'),'hex'),p_tenant,c);return app_private.wa_account(p_tenant,c)||jsonb_build_object('token',token);end if;
 if p_action='track' then
 if length(coalesce(p_data->>'key',''))<30 then raise exception 'Acesso inválido';end if;select jsonb_build_object('id',id,'ticketNumber',ticket_number,'status',app_private.wa_phase(status,motoboy_id),'updated',updated_at) into result from public.orders where tenant_id=p_tenant and id=(p_data->>'orderId')::uuid and idempotency_key=p_data->>'key';if result is null then raise exception 'Pedido indisponível';end if;return result;end if;
 if p_action='claim' then
 update app_private.wa_outbox set state='uncertain',last_error='Confirme o envio antes de reenviar' where tenant_id=p_tenant and state='processing' and available_at<now()-interval '5 minutes';
 with rows as(select q.id from app_private.wa_outbox q where tenant_id=p_tenant and state='pending' and available_at<=now() and (p_data->>'dedupe' is null or q.dedupe=p_data->>'dedupe') order by created_at for update skip locked limit 10),upd as(update app_private.wa_outbox q set state=case when (q.kind='otp' and q.created_at<now()-interval '5 minutes') or (q.kind<>'otp' and q.created_at<now()-interval '24 hours') or (q.kind<>'otp' and not exists(select 1 from public.customers c where c.id=q.customer_id and c.tenant_id=q.tenant_id and c.portal_deleted_at is null and c.phone_verified_at is not null and case when q.kind='birthday' then c.whatsapp_marketing else c.whatsapp_updates end)) then 'cancelled' else 'processing' end,attempts=q.attempts+1,available_at=now() from rows where q.id=rows.id returning q.*) select coalesce(jsonb_agg(to_jsonb(upd)) filter(where state='processing'),'[]'::jsonb) into result from upd;return result;end if;
 if p_action='ack' then
 select * into e from app_private.wa_outbox where tenant_id=p_tenant and id=(p_data->>'id')::uuid and state='processing' for update;if e.id is null then return '{}';end if;
 update app_private.wa_outbox set state='sent',sent_at=now(),provider_id=p_data->>'providerId',payload=case when kind='otp' then '{}'::jsonb else payload end,last_error=null where id=e.id;
 if e.kind='birthday' then update public.campaigns set active=true,sent_at=now(),expires_at=now()+interval '72 hours' where id=(e.payload->>'campaignId')::uuid and tenant_id=p_tenant and not used and exists(select 1 from public.customers where id=e.customer_id and portal_deleted_at is null);end if;return '{}';end if;
 if p_action='failure' then update app_private.wa_outbox set state=case when p_data->>'state'='pending' and attempts<5 then 'pending' when p_data->>'state'='uncertain' then 'uncertain' else 'failed' end,available_at=now()+make_interval(secs=>least(3600,60*power(2,attempts)::int)),last_error=left(p_data->>'error',160) where tenant_id=p_tenant and id=(p_data->>'id')::uuid and state='processing';return '{}';end if;
 if p_action='delivery' then update app_private.wa_outbox set state=case when state='read' then 'read' when state='delivered' and p_data->>'state'='sent' then 'delivered' else p_data->>'state' end where tenant_id=p_tenant and provider_id=p_data->>'providerId' and p_data->>'state' in('sent','delivered','read','failed');return '{}';end if;
 if p_action='unsubscribe' then update public.customers set whatsapp_updates=false,whatsapp_marketing=false where tenant_id=p_tenant and app_private.wa_phone(phone)=app_private.wa_phone(p_data->>'phone');return '{}';end if;
 c:=app_private.wa_customer(p_tenant,p_token);if c is null then raise exception 'Sessão do cliente expirada. Confirme seu WhatsApp novamente.';end if;
 if p_action='account' then return app_private.wa_account(p_tenant,c);end if;
 if p_action='logout' then delete from app_private.wa_sessions where tenant_id=p_tenant and token_hash=encode(extensions.digest(p_token,'sha256'),'hex');return '{}';end if;
 if p_action='profile' then bdate:=nullif(p_data->>'birthDate','')::date;if bdate>current_date or bdate<date '1900-01-01' then raise exception 'Data de aniversário inválida';end if;update public.customers set birth_date=bdate,whatsapp_updates=coalesce((p_data->>'updates')::boolean,false),whatsapp_marketing=coalesce((p_data->>'marketing')::boolean,false) where id=c and tenant_id=p_tenant;return app_private.wa_account(p_tenant,c);end if;
 if p_action='delete' then
 if not exists(select 1 from app_private.wa_sessions where customer_id=c and token_hash=encode(extensions.digest(p_token,'sha256'),'hex') and created_at>now()-interval '15 minutes') then raise exception 'Confirme seu WhatsApp novamente antes de excluir o cadastro.';end if;
 if exists(select 1 from public.orders o join public.customers x on x.id=c where o.tenant_id=p_tenant and app_private.wa_phone(o.customer_phone)=app_private.wa_phone(x.phone) and lower(o.status) not in('concluído','concluido','finalizado','entregue','recusado','cancelado')) then raise exception 'Aguarde a conclusão dos seus pedidos antes de excluir o cadastro.';end if;
 update public.campaigns set active=false,customer_name='',customer_phone='' where tenant_id=p_tenant and customer_id=c;update app_private.wa_outbox set state='cancelled',phone='',payload='{}' where tenant_id=p_tenant and customer_id=c and state in('pending','failed','uncertain');
 update public.orders o set customer_name='Cliente (cadastro excluído)',customer_phone='',customer_address='' from public.customers x where x.id=c and o.tenant_id=p_tenant and app_private.wa_phone(o.customer_phone)=app_private.wa_phone(x.phone);
 update public.customers set name='Cadastro excluído',phone='removed-'||id,address='',notes='',birth_date=null,whatsapp_updates=false,whatsapp_marketing=false,portal_deleted_at=now(),auth_user_id=null,crm_profile='{}',favorite_items='[]' where id=c;delete from app_private.wa_sessions where customer_id=c;return '{}';end if;
 raise exception 'Ação indisponível';end$$;
create function app_private.wa_tick() returns void language plpgsql security definer set search_path='' as $$declare w app_private.wa_connections;begin
 perform app_private.wa_queue_birthdays();for w in select * from app_private.wa_connections where enabled loop perform net.http_post(url:='https://awgqpfdfsyslpqpfzoul.supabase.co/functions/v1/customer-whatsapp',headers:=jsonb_build_object('Content-Type','application/json','x-worker-secret',w.worker_secret),body:=jsonb_build_object('tenantId',w.tenant_id,'action','dispatch'));end loop;
 delete from app_private.wa_sessions where expires_at<now();delete from app_private.wa_otps where created_at<now()-interval '1 day';update app_private.wa_outbox set phone='',payload='{}' where created_at<now()-interval '7 days' and state not in('pending','processing');end$$;
revoke all on app_private.wa_connections,app_private.wa_otps,app_private.wa_sessions,app_private.wa_outbox,app_private.wa_birthdays from public,anon,authenticated;
revoke all on function public.customer_whatsapp_api(uuid,text,jsonb,text,uuid) from public,anon,authenticated;
grant execute on function public.customer_whatsapp_api(uuid,text,jsonb,text,uuid) to service_role;
revoke all on function app_private.wa_phone(text),app_private.wa_phase(text,uuid),app_private.wa_customer(uuid,text),app_private.wa_account(uuid,uuid),app_private.wa_order_event(),app_private.wa_queue_birthdays(timestamptz),app_private.wa_tick() from public,anon,authenticated;
select cron.schedule('loyolas-whatsapp-automation','* * * * *','select app_private.wa_tick()');
